// zigonly Phase 1 — autogenerated link stubs.
// Every symbol the Zig code used to call from C/shim is stubbed here as
// a noreturn @panic. As clusters get ported, real implementations replace
// individual stubs (delete the corresponding line here).
//
// Regenerate the symbol list with:
//   zig build -Dconfig=nano 2>&1 | grep -oE 'undefined symbol: _[a-zA-Z_][a-zA-Z0-9_]*' | sed 's/undefined symbol: _//' | sort -u

const mirrors = @import("mp_mirrors.zig");

// ── layout mirror constants ─────────────────────────────────────────
// Real `usize` data symbols backing the `extern const npy_mirror_*: usize`
// declarations in `mp_mirrors.zig`. Previously these were defined as
// `noreturn` function stubs; the linker resolved the externs to the
// function entry-point address (meaningless garbage when read as a size),
// so any `assertLayout()` run would either pass by coincidence or compare
// against ~48 bits of instruction bytes. Defining them as real comptime
// `@sizeOf`/`@offsetOf` values makes the asserts self-consistent and
// document the layout contract honestly.
//
// Subobj is intentionally `offsetOf(members) + sizeOf(MpMap)` — the
// flexible `subobj[]` array starts immediately past the embedded `members`
// map (see the matching assert in `mp_mirrors.zig:304`).

pub export const npy_mirror_sizeof_mp_map_t: usize = @sizeOf(mirrors.MpMap);
pub export const npy_mirror_sizeof_mp_obj_dict_t: usize = @sizeOf(mirrors.MpObjDict);
pub export const npy_mirror_sizeof_mp_obj_list_t: usize = @sizeOf(mirrors.MpObjList);
pub export const npy_mirror_sizeof_mp_obj_module_t: usize = @sizeOf(mirrors.MpObjModule);
pub export const npy_mirror_sizeof_mp_obj_str_t: usize = @sizeOf(mirrors.MpObjStr);
pub export const npy_mirror_sizeof_mp_obj_tuple_t: usize = @sizeOf(mirrors.MpObjTuple);
pub export const npy_mirror_sizeof_mp_obj_closure_t: usize = @sizeOf(mirrors.MpObjClosure);
pub export const npy_mirror_sizeof_mp_obj_bound_meth_t: usize = @sizeOf(mirrors.MpObjBoundMeth);
pub export const npy_mirror_sizeof_mp_obj_fun_bc_t: usize = @sizeOf(mirrors.MpObjFunBc);
pub export const npy_mirror_sizeof_mp_code_state_t: usize = @sizeOf(mirrors.MpCodeState);
pub export const npy_mirror_sizeof_mp_exc_stack_t: usize = @sizeOf(mirrors.MpExcStack);
pub export const npy_mirror_sizeof_mp_obj_exception_t: usize = @sizeOf(mirrors.MpObjException);
